import { mergeRecords } from './merge-records.mjs';

function cursorKey(cursor) {
  return cursor === null ? '\0__null__\0' : cursor;
}

function assertMaxPages(maxPages) {
  if (!Number.isInteger(maxPages) || maxPages <= 0) {
    throw new RangeError('maxPages must be a positive integer');
  }
}

function assertRecord(record) {
  if (record === null || typeof record !== 'object') {
    throw new TypeError('invalid record');
  }
  const { id } = record;
  const idOk =
    typeof id === 'string' ||
    (typeof id === 'number' && Number.isFinite(id));
  if (!idOk) {
    throw new TypeError('invalid record id');
  }
}

function assertPage(page) {
  if (page === null || typeof page !== 'object') {
    throw new TypeError('invalid page');
  }
  if (!Array.isArray(page.items)) {
    throw new TypeError('invalid page items');
  }
  const { nextCursor } = page;
  if (nextCursor !== null && typeof nextCursor !== 'string') {
    throw new TypeError('invalid nextCursor');
  }
  for (const item of page.items) {
    assertRecord(item);
  }
}

export async function collectPages(fetchPage, { initialCursor = null, maxPages = 100 } = {}) {
  assertMaxPages(maxPages);

  const seenCursors = new Set();
  let cursor = initialCursor;
  const records = [];

  for (let count = 0; count < maxPages; count++) {
    const key = cursorKey(cursor);
    if (seenCursors.has(key)) {
      throw new Error('repeated cursor');
    }
    seenCursors.add(key);

    const page = await fetchPage(cursor);
    assertPage(page);
    mergeRecords(records, page.items);

    if (page.nextCursor === null) {
      return records;
    }
    cursor = page.nextCursor;
  }

  throw new Error('page limit reached');
}

